// Called by the /api/tools/escalate endpoint (N8N_ESCALATION_WEBHOOK_URL)
// with the envelope the tool already decided. What the caller was promised
// (toldCaller) was written by the tool, not by a model -- that promise
// depends on staffing and the hour, and it must not drift.

const body = $input.first().json;
const str = (v) => (v === undefined || v === null ? '' : String(v).trim());

return [{
  json: {
    escalation_id: str(body.escalationId || body.escalation_id),
    call_id: str(body.callId || body.call_id),
    category: str(body.category || 'confused'),
    urgency: str(body.urgency || 'today'),
    summary: str(body.summary || '(no summary given)'),
    caller_said: str(body.callerSaid || body.caller_said),
    action: str(body.action || 'message_taken'),
    told_caller: str(body.toldCaller || body.told_caller),
    open_now: body.openNow === true || body.open_now === true
  }
}];

// The routing table from docs/02-escalation-policy.md:
//
//   urgency            business hours      after hours
//   now                warm transfer       message + SMS on-call
//   today              message, flagged    queued for the morning
//   next_business_day  message             message
//
// 'Message' here means the escalation row + the console queue (v_escalation_queue),
// which the tool endpoint already wrote. This workflow owns the two things
// that leave the building: the after-hours SMS to the on-call number, and the
// Slack line. A warm transfer rides the voice transport, which is not wired
// yet -- until it is, 'now' during business hours degrades to the queue plus
// Slack, which is exactly what the escalate tool already told the caller
// (toldCaller) it would do.

const env = $input.first().json;
const n = $('Normalise the envelope').first().json;

const urgency = ['now', 'today', 'next_business_day'].includes(n.urgency) ? n.urgency : 'today';
const escalation_number = env.escalation_number || '';
const caller_phone = env.caller_phone || '';
const business_name = env.business_name || 'the practice';

const afterHours = !n.open_now;
const needs_oncall_sms = urgency === 'now' && afterHours && escalation_number !== '';
const needs_slack = urgency === 'now' || urgency === 'today';

const hoursLine = afterHours ? 'after hours' : 'business hours';
const line = '• *' + business_name + '* — ' + urgency + ' (' + hoursLine + '): ' + n.summary;
const callerLine = caller_phone ? '\n• Caller: ' + caller_phone : '';
const saidLine = '\n• Caller was told: ' + n.told_caller;

const slack_text = '⚠️ *Escalation ' + urgency + '*\n' + line + callerLine + saidLine;
const sms_text = 'URGENT escalation for ' + business_name + ': ' + n.summary + '. Caller: ' + caller_phone;

return [{
  json: {
    escalation_id: n.escalation_id,
    call_id: n.call_id,
    category: n.category,
    urgency,
    action: n.action,
    summary: n.summary,
    after_hours: afterHours,
    needs_oncall_sms,
    needs_slack,
    escalation_number,
    caller_phone,
    business_name,
    slack_text,
    sms_text
  }
}];
